CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "deleted_entities" ("entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "deleted_at" INTEGER NOT NULL, PRIMARY KEY ("entity_type", "entity_id"));
CREATE TABLE "ecampus_courses" ("id" TEXT NOT NULL, "source_scope_id" TEXT NOT NULL, "external_course_key" TEXT NULL, "name" TEXT NOT NULL, "tag_id" TEXT NULL REFERENCES tags (id), "last_observed_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("source_scope_id", "external_course_key"));
CREATE TABLE "ecampus_items" ("id" TEXT NOT NULL, "source_scope_id" TEXT NOT NULL, "course_id" TEXT NULL REFERENCES ecampus_courses (id), "external_key" TEXT NULL, "source_title" TEXT NOT NULL, "source_course" TEXT NULL, "source_type" TEXT NULL, "source_start_at" INTEGER NULL, "source_end_at" INTEGER NULL, "task_id" TEXT NULL UNIQUE REFERENCES tasks (id), "import_state" TEXT NOT NULL, "first_observed_at" INTEGER NOT NULL, "last_observed_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("source_scope_id", "external_key"), CHECK ((import_state = 'imported' AND task_id IS NOT NULL) OR (import_state IN ('ignored','unreviewed') AND task_id IS NULL)));
CREATE TABLE "folders" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT NULL, "icon" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "deleted_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "import_sessions" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL DEFAULT 'ecampus', "input_method" TEXT NOT NULL DEFAULT 'webview_html', "source_scope_id" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "state" TEXT NOT NULL, "applied_count" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "local_notification_schedules" ("task_id" TEXT NOT NULL REFERENCES tasks (id), "platform_notification_id" INTEGER NULL UNIQUE, "scheduled_at" INTEGER NULL, "last_error" TEXT NULL, PRIMARY KEY ("task_id"));
CREATE TABLE "migration_issues" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entity_id" TEXT NOT NULL, "reason" TEXT NOT NULL, "legacy_data" TEXT NOT NULL);
CREATE TABLE "sub_tasks" ("id" TEXT NOT NULL, "task_id" TEXT NOT NULL REFERENCES tasks (id), "title" TEXT NOT NULL, "position" INTEGER NOT NULL DEFAULT 0, "completed_at" INTEGER NULL, "deleted_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "tags" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "deleted_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "task_reminders" ("id" TEXT NOT NULL UNIQUE, "task_id" TEXT NOT NULL REFERENCES tasks (id), "enabled" INTEGER NOT NULL CHECK ("enabled" IN (0, 1)), "offset_minutes" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("task_id"), CHECK (offset_minutes >= 0));
CREATE TABLE "task_tags" ("task_id" TEXT NOT NULL REFERENCES tasks (id), "tag_id" TEXT NOT NULL REFERENCES tags (id), "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("task_id", "tag_id"));
CREATE TABLE "tasks" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "due_date" INTEGER NULL, "priority" TEXT NULL, "memo" TEXT NULL, "folder_id" TEXT NULL REFERENCES folders (id), "sort_order" INTEGER NOT NULL DEFAULT 0, "completed_at" INTEGER NULL, "deleted_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK (priority IS NULL OR priority IN ('high','medium','low')));
CREATE INDEX subtasks_parent ON sub_tasks(task_id, deleted_at, position);
CREATE INDEX task_tags_tag ON task_tags(tag_id, deleted_at);
CREATE INDEX tasks_active_order ON tasks(deleted_at, completed_at, sort_order, created_at);
CREATE INDEX tasks_due ON tasks(due_date);
CREATE INDEX tasks_folder ON tasks(folder_id);
PRAGMA user_version = 6;
